import{_ as a,o as t,c as _,a3 as p}from"./chunks/framework.DdpBa4_E.js";const s="/ReadBooks/assets/image-003.nZSA8Liq.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/90-团块次代中八成人口今后仍将居住原地.md","filePath":"books/xialiu-shehui/90-团块次代中八成人口今后仍将居住原地.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/90-团块次代中八成人口今后仍将居住原地.md"};function i(r,e,l,n,d,u){return t(),_("div",null,[...e[0]||(e[0]=[p('<h2 id="团块次代中八成人口今后仍将居住原地" tabindex="-1">团块次代中八成人口今后仍将居住原地 <a class="header-anchor" href="#团块次代中八成人口今后仍将居住原地" aria-label="Permalink to &quot;团块次代中八成人口今后仍将居住原地&quot;">​</a></h2><p>为了进一步验证此种趋势，Culture Studies研究所接受日本“居住环境研究所”的委托，对其实施调查所取得的数据进行了重新统计。</p><p>本次调查的对象为居住在首都圈一都三县、在2003年时年龄为27—33岁，也就是1970—1976年期间（相当于第二次生育高峰期）出生的男女，主要询问从现在起的五年至十年后，即2010年左右他们会居住在哪里。选取的样本数为700人，将一都三县划分为14个区域，由于对不同地域的抽样比例分配得相当精密，所以统计结果的可信度应该是相当高的。</p><p>以地域划分为基准，对今后五至十年第二次生育高峰期出生的一代人究竟会居住在哪里进行了预测，详情如表8-4所示。</p><p>例如被调查者中目前有73人居住在横滨，但可以看到其中65人在2010年仍然会住在横滨；有49人现在居住在埼玉县的中心，也就是浦和市和大宫市一带，但到2010年仍然住在那里的人减少至41人。</p><p>目前居住在23区中部的有27人，将来则可能达到29人，虽然只增加了两个人，但由于实际人口是抽样调查数的大约6000倍，所以实际将会增加12000人。在23区中部，仅团块次代就增加12000人，可见增加的幅度是相当大的。不过这是以原本人口较少的都市中心为分母得出的结果，如果将郊外人口数作为分母来计算的话，则不仅不会向都市中心移动，甚至向本县内其他地域移动的态势也几乎看不出来。</p><p>表8-4　2010年左右会居住在哪里？</p><p><img src="'+s+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所根据“居住环境研究所”的调查数据进行的重新统计事实上，在这14个地域平均有83%的人今后仍然会住在同一地域，例如从埼玉县西南部搬到埼玉县中部的人数为零。据此将首都圈一都三县的数据进行加权后重新统计，竟有多达90%的人回答今后仍将会居住在原地，而且大多数人都表示，即使要搬家也只会在现在所住地方附近的范围内。也就是说大宫的人不会搬到春日部去，狭山的人不会来浦和，厚木的人也不会迁到横滨来。大多数人已经将居住范围固定在了目前所住地方沿线的地域内。</p><p>居住地为什么会变得如此固定化呢？因为到团块世代为止，许多人在年轻的时候从其他地方移居到东京等大都市圈。但上世纪60年代出生的人当中，从一开始就住在大都市圈的人数大为增加，他们属于父母那一代就来到大都市圈并一直在那里定居的世代。</p><p>而一大批团块次代的人是在郊外长大的，对他们来说郊外就是自己的故乡。不过那样的话，人们就不会拼命想要从各地来到东京。或许是以为从郊外很快就可以到都市中心，但不少人其实从小学到中学念的一直都是郊外的公立学校，直到上了大学才终于来到都市中心。非但如此，由于大学也在不断向郊外迁移，因此即便上了大学也还是不怎么去都市中心的人并不少见。</p><p>高中毕业后就参加工作的人，愈加离不开自己居住的地方。现在郊外也有豪华的百货公司和时装商厦，所以没有必要特地去都市中心购物，于是便诞生了“当地一族”。“当地一族”的价值观就是在郊外这样的“村子”里过着无忧无虑的生活。</p>',12)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
